    <div class="grid gap-6 xl:grid-cols-[1fr_340px]"><section class="rounded-2xl border border-slate-200 bg-white p-6"><div class="flex justify-between text-sm"><div><p class="text-slate-500">Issued</p><p>{{ $invoice->issue_date->format('M j, Y') }}</p></div><div><p class="text-slate-500">Due</p><p>{{ $invoice->due_date->format('M j, Y') }}</p></div></div><table class="mt-6 w-full text-sm"><thead class="border-b text-slate-500"><tr><th class="py-3 text-left">Description</th><th>Qty</th><th class="text-right">Amount</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr class="border-b border-slate-100"><td class="py-4">{{ $item->description }}</td><td class="text-center">{{ $item->quantity }}</td><td class="text-right">{{ $invoice->currency }} {{ number_format($item->total,2) }}</td></tr>@endforeach</tbody></table><div class="ml-auto mt-5 max-w-xs space-y-2 text-sm"><div class="flex justify-between"><span>Subtotal</span><span>{{ number_format($invoice->subtotal,2) }}</span></div><div class="flex justify-between"><span>Discount</span><span>-{{ number_format($invoice->discount,2) }}</span></div><div class="flex justify-between text-sm"><span>Tax</span><span>{{ number_format($invoice->tax_amount,2) }}</span></div><div class="flex justify-between border-t pt-2 text-lg font-semibold"><span>Total</span><span>{{ $invoice->currency }} {{ number_format($invoice->total,2) }}</span></div><div class="flex justify-between text-emerald-700"><span>Paid</span><span>{{ number_format($invoice->paidAmount(),2) }}</span></div><div class="flex justify-between font-medium"><span>Remaining</span><span>{{ number_format($invoice->remainingAmount(),2) }}</span></div></div></section>
